import sys
from decimal import Decimal


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        a_str, op, b_str = parts
        a = Decimal(a_str)
        b = Decimal(b_str)
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        else:
            if b == 0:
                print("ERROR")
                continue
            result = round(a / b, 10)
        # Format the result
        if result == 0:
            print("0")
        elif result.is_integer():
            print(int(result))
        else:
            s = str(result)
            if "." in s:
                integer_part, fractional_part = s.split(".", 1)
            else:
                integer_part = s
                fractional_part = ""
            formatted_result = integer_part
            if fractional_part:
                formatted_result += "." + fractional_part.lstrip("0")
                if not formatted_result:
                    formatted_result = "0"
            print(formatted_result)


if __name__ == "__main__":
    main()
